const vertexShaderSource = `
uniform float u_time;
varying vec2 vUv;
vec3 mod289(vec3 x){
return x-floor(x*(1.0/289.0))*289.0;
}
vec2 mod289(vec2 x){
return x-floor(x*(1.0/289.0))*289.0;
}
vec3 permute(vec3 x){
return mod289(((x*34.0)+1.0)*x);
}
float snoise(vec2 v){
const vec4 C=vec4(0.211324865405187,0.366025403784439,-0.577350269189626,0.024390243902439);
vec2 i=floor(v+dot(v,C.yy));
vec2 x0=v-i+dot(i,C.xx);
vec2 i1=x0.x>x0.y?vec2(1.0,0.0):vec2(0.0,1.0);
vec4 x12=x0.xyxy+C.xxzz;
x12.xy-=i1;
i=mod289(i);
vec3 p=permute(permute(i.y+vec3(0.0,i1.y,1.0))+i.x+vec3(0.0,i1.x,1.0));
vec3 m=max(0.5-vec3(dot(x0,x0),dot(x12.xy,x12.xy),dot(x12.zw,x12.zw)),0.0);
m=m*m;
m=m*m;
vec3 x=2.0*fract(p*C.www)-1.0;
vec3 h=abs(x)-0.5;
vec3 ox=floor(x+0.5);
vec3 a0=x-ox;
m*=1.79284291400159-0.85373472095314*(a0*a0+h*h);
vec3 g;
g.x=a0.x*x0.x+h.x*x0.y;
g.y=a0.y*x12.x+h.y*x12.y;
g.z=a0.z*x12.z+h.z*x12.w;
return 130.0*dot(m,g);
}
void main(){
vUv=uv;
float n1=snoise(position.xy*0.1+vec2(u_time*0.2,u_time*0.2));
float n2=snoise(position.xy*0.5+vec2(u_time*0.1,u_time*0.1));
float displacement=(n1+n2)*0.2;
vec3 newPosition=vec3(position.x,position.y,displacement);
gl_Position=projectionMatrix*modelViewMatrix*vec4(newPosition,1.0);
}
`;
const fragmentShaderSource = `
uniform float u_time;
varying vec2 vUv;
vec3 mod289(vec3 x){
return x-floor(x*(1.0/289.0))*289.0;
}
vec2 mod289(vec2 x){
return x-floor(x*(1.0/289.0))*289.0;
}
vec3 permute(vec3 x){
return mod289(((x*34.0)+1.0)*x);
}
float snoise(vec2 v){
const vec4 C=vec4(0.211324865405187,0.366025403784439,-0.577350269189626,0.024390243902439);
vec2 i=floor(v+dot(v,C.yy));
vec2 x0=v-i+dot(i,C.xx);
vec2 i1=x0.x>x0.y?vec2(1.0,0.0):vec2(0.0,1.0);
vec4 x12=x0.xyxy+C.xxzz;
x12.xy-=i1;
i=mod289(i);
vec3 p=permute(permute(i.y+vec3(0.0,i1.y,1.0))+i.x+vec3(0.0,i1.x,1.0));
vec3 m=max(0.5-vec3(dot(x0,x0),dot(x12.xy,x12.xy),dot(x12.zw,x12.zw)),0.0);
m=m*m;
m=m*m;
vec3 x=2.0*fract(p*C.www)-1.0;
vec3 h=abs(x)-0.5;
vec3 ox=floor(x+0.5);
vec3 a0=x-ox;
m*=1.79284291400159-0.85373472095314*(a0*a0+h*h);
vec3 g;
g.x=a0.x*x0.x+h.x*x0.y;
g.y=a0.y*x12.x+h.y*x12.y;
g.z=a0.z*x12.z+h.z*x12.w;
float noiseValue=130.0*dot(m,g);
vec3 color1=vec3(0.0,0.2,0.5);
vec3 color2=vec3(0.0,0.48,1.0);
vec3 specular=vec3(0.8,0.9,1.0);
float noiseMix=snoise(vUv*3.0+vec2(u_time*0.02,u_time*0.02));
float mixVal=(noiseMix+1.0*0.5);
vec3 baseColor=mix(color1,color2,clamp(mixVal,0.0,1.0));
float shine=smoothstep(0.7,0.8,noiseValue);
vec3 finalColor=mix(baseColor,specular,shine*0.5);
gl_FragColor=vec4(finalColor,1.0);
}
`;
