function init3DBackground(){
const canvas=document.getElementById("canvas-bg");
if(!canvas||typeof THREE==="undefined"){
return;
}
bgScene=new THREE.Scene();
bgCamera=new THREE.PerspectiveCamera(75,window.innerWidth/window.innerHeight,0.1,1000);
bgRenderer=new THREE.WebGLRenderer({canvas:canvas,alpha:true,antialias:true});
bgRenderer.setSize(window.innerWidth,window.innerHeight);
bgRenderer.setPixelRatio(window.devicePixelRatio||1);
bgClock=new THREE.Clock();
const geometry=new THREE.PlaneGeometry(20,20,100,100);
bgUniforms={u_time:{value:0}};
const material=new THREE.ShaderMaterial({vertexShader:vertexShaderSource,fragmentShader:fragmentShaderSource,uniforms:bgUniforms});
const mesh=new THREE.Mesh(geometry,material);
mesh.rotation.x=-Math.PI/4.5;
bgScene.add(mesh);
bgCamera.position.z=3.5;
animate3D();
}
function animate3D(){
if(!bgRenderer||!bgScene||!bgCamera||!bgClock||!bgUniforms){
return;
}
requestAnimationFrame(animate3D);
bgUniforms.u_time.value=bgClock.getElapsedTime();
bgRenderer.render(bgScene,bgCamera);
}
function onWindowResize(){
if(!bgRenderer||!bgCamera){
return;
}
bgCamera.aspect=window.innerWidth/window.innerHeight;
bgCamera.updateProjectionMatrix();
bgRenderer.setSize(window.innerWidth,window.innerHeight);
}
function generateSessionId(){
const id="session_"+Date.now()+"_"+Math.random().toString().slice(2,9);
try{
localStorage.setItem("sessionId",id);
}
catch(e){}
return id;
}
function openSidebar(){
if(!sidebar||!sidebarOverlay){
return;
}
sidebar.classList.add("open");
sidebarOverlay.classList.add("visible");
renderPastChats();
}
function closeSidebar(){
if(!sidebar||!sidebarOverlay){
return;
}
sidebar.classList.remove("open");
sidebarOverlay.classList.remove("visible");
}
function renderPastChats(){
if(!pastChatsContainer){
return;
}
pastChatsContainer.innerHTML="";
const sortedSessions=[...allSessions].sort((a,b)=>b.timestamp-a.timestamp);
sortedSessions.forEach((session,index)=>{
const chatItem=document.createElement("div");
let cls="past-chat-item";
if(session.id===sessionId){
cls+=" active";
}
chatItem.className=cls;
const title=session.title||( "Chat "+String(allSessions.length-index));
let dateText="";
try{
dateText=new Date(session.timestamp).toLocaleString("hu-HU",{year:"numeric",month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"});
}
catch(e){
dateText=String(session.timestamp);
}
chatItem.innerHTML="<div class=\"past-chat-title\">"+title+"</div><div class=\"past-chat-date\">"+dateText+"</div>";
chatItem.addEventListener("click",()=>{
loadChatSession(session.id);
closeSidebar();
});
pastChatsContainer.appendChild(chatItem);
});
}
function saveCurrentSession(){
if(conversationHistory.length===0){
return;
}
const existingIndex=allSessions.findIndex(s=>s.id===sessionId);
const firstMessage=conversationHistory[0];
let title="Új chat";
if(firstMessage&&typeof firstMessage.content==="string"&&firstMessage.content.length>0){
title=firstMessage.content.slice(0,50);
}
const sessionData={id:sessionId,title:title,timestamp:Date.now(),messageCount:conversationHistory.length};
if(existingIndex>=0){
allSessions[existingIndex]=sessionData;
}
else{
allSessions.push(sessionData);
}
try{
localStorage.setItem("allSessions",JSON.stringify(allSessions));
}
catch(e){}
}
function createNewChat(){
saveCurrentSession();
sessionId=generateSessionId();
conversationHistory=[];
if(chatHistory){
chatHistory.innerHTML="";
}
addMessageToHistory("Üdvözlöm! Kattintson a ‘+’ gombra AI mély kutatás indításához, vagy írjon egyszerű üzenetet az AI asszisztensnek.","ai",null,false,false);
closeSidebar();
}
function loadChatSession(newSessionId){
saveCurrentSession();
sessionId=newSessionId;
try{
localStorage.setItem("sessionId",sessionId);
}
catch(e){}
conversationHistory=[];
if(chatHistory){
chatHistory.innerHTML="";
}
loadChatHistory();
}
function handleSwipe(){
const swipeDistance=touchEndX-touchStartX;
const minSwipeDistance=50;
if(swipeDistance>minSwipeDistance&&touchStartX<50){
openSidebar();
}
else if(swipeDistance<-minSwipeDistance&&sidebar&&sidebar.classList.contains("open")){
closeSidebar();
}
}
async function loadChatHistory(){
try{
const res=await fetch("/api/chat/history/"+encodeURIComponent(sessionId));
if(!res.ok){
console.warn("Could not load chat history");
return;
}
const data=await res.json();
conversationHistory=(data.messages||[]).filter(m=>m&&m.role&&m.content);
conversationHistory.forEach(msg=>{
if(msg.role==="user"||msg.role==="assistant"){
addMessageToHistory(msg.content,msg.role==="user"?"user":"ai",null,false,false);
}
});
}
catch(e){
console.warn("Could not load chat history",e);
}
}
async function saveChatMessage(role,content){
try{
await fetch("/api/chat/history/"+encodeURIComponent(sessionId),{
method:"POST",
headers:{"Content-Type":"application/json"},
body:JSON.stringify({message:{role:role,content:content}})
});
saveCurrentSession();
}
catch(e){
console.warn("Failed to save chat message",e);
}
}
