async function sendChatMessage(prompt){
addMessageToHistory(prompt,"user",null,false,true);
const streamingMsgId="streaming-"+Date.now().toString();
addMessageToHistory("","ai",streamingMsgId,false,false);
conversationHistory.push({role:"user",content:prompt});
const userSavePromise=saveChatMessage("user",prompt);
const contextWindow=conversationHistory.slice(Math.max(conversationHistory.length-10,0));
if(sendButton){
sendButton.disabled=true;
}
try{
const res=await fetch(apiUrl,{
method:"POST",
headers:{"Content-Type":"application/json"},
body:JSON.stringify({messages:contextWindow,temperature:0.7})
});
if(!res.ok){
let errorText="";
try{
errorText=await res.text();
}
catch(e){}
throw new Error("HTTP "+res.status+": "+res.statusText+" "+errorText);
}
if(!res.body){
throw new Error("Streaming body is not available");
}
const reader=res.body.getReader();
const decoder=new TextDecoder();
let fullResponse="";
while(true){
const readResult=await reader.read();
if(readResult.done){
break;
}
const chunk=decoder.decode(readResult.value,{stream:true});
const lines=chunk.split("\n");
for(const rawLine of lines){
const line=rawLine.trim();
if(!line.startsWith("data: ")){
continue;
}
const payload=line.slice(6).trim();
if(!payload){
continue;
}
let data;
try{
data=JSON.parse(payload);
}
catch(e){
continue;
}
if(data.error){
throw new Error(String(data.error));
}
if(data.content){
fullResponse+=String(data.content);
updateStreamingMessage(streamingMsgId,fullResponse);
}
if(data.done){
conversationHistory.push({role:"assistant",content:fullResponse});
await Promise.all([userSavePromise,saveChatMessage("assistant",fullResponse)]);
}
}
}
finalizeStreamingMessage(streamingMsgId,fullResponse);
}
catch(e){
updateMessageInHistory(streamingMsgId,"Hiba történt a válasz lekérése közben.","ai",true);
console.error(e);
}
finally{
if(sendButton){
sendButton.disabled=false;
}
}
}
