function parseCommaList(value){
if(!value){
return [];
}
return value.split(",").map(v=>v.trim()).filter(v=>v.length>0);
}
function buildOptionsFromForm(){
const searchTypeEl=document.getElementById("search-type");
const categoryEl=document.getElementById("category");
const userLocationEl=document.getElementById("user-location");
const startDateEl=document.getElementById("start-date");
const endDateEl=document.getElementById("end-date");
const startCrawlDateEl=document.getElementById("start-crawl-date");
const endCrawlDateEl=document.getElementById("end-crawl-date");
const includeDomainsEl=document.getElementById("include-domains");
const excludeDomainsEl=document.getElementById("exclude-domains");
const includeTextEl=document.getElementById("include-text");
const excludeTextEl=document.getElementById("exclude-text");
const fullTextEl=document.getElementById("full-text");
const aiSummaryEl=document.getElementById("ai-summary");
const subpagesEl=document.getElementById("subpages");
const subpageTargetEl=document.getElementById("subpage-target");
const livecrawlEl=document.getElementById("livecrawl");
const livecrawlTimeoutEl=document.getElementById("livecrawl-timeout");
const linksEl=document.getElementById("links");
const searchType=(searchTypeEl&&searchTypeEl.value)||"auto";
const category=(categoryEl&&categoryEl.value)||null;
const userLocationRaw=(userLocationEl&&userLocationEl.value)||"";
const userLocation=userLocationRaw.trim()||null;
const startDateVal=(startDateEl&&startDateEl.value)||null;
const endDateVal=(endDateEl&&endDateEl.value)||null;
const startCrawlDateVal=(startCrawlDateEl&&startCrawlDateEl.value)||null;
const endCrawlDateVal=(endCrawlDateEl&&endCrawlDateEl.value)||null;
const includeDomainsList=parseCommaList(includeDomainsEl?includeDomainsEl.value:"");
const excludeDomainsList=parseCommaList(excludeDomainsEl?excludeDomainsEl.value:"");
const includeTextRaw=(includeTextEl&&includeTextEl.value)||"";
const includeText=includeTextRaw.trim()||null;
const excludeTextRaw=(excludeTextEl&&excludeTextEl.value)||"";
const excludeText=excludeTextRaw.trim()||null;
const fullText=!!(fullTextEl&&fullTextEl.checked);
const aiSummary=!!(aiSummaryEl&&aiSummaryEl.checked);
const subpages=!!(subpagesEl&&subpagesEl.checked);
let subpageTargetValue=3;
if(subpageTargetEl&&subpageTargetEl.value){
const parsed=parseInt(subpageTargetEl.value,10);
if(!Number.isNaN(parsed)){
subpageTargetValue=parsed;
}
}
const livecrawlVal=(livecrawlEl&&livecrawlEl.value)||"fallback";
const livecrawlTimeoutVal=(livecrawlTimeoutEl&&livecrawlTimeoutEl.value)||null;
const linksVal=!!(linksEl&&linksEl.checked);
return{
searchType:searchType,
category:category,
userLocation:userLocation,
startDate:startDateVal,
endDate:endDateVal,
startCrawlDate:startCrawlDateVal,
endCrawlDate:endCrawlDateVal,
includeDomains:includeDomainsList.length>0?includeDomainsList:null,
excludeDomains:excludeDomainsList.length>0?excludeDomainsList:null,
includeText:includeText,
excludeText:excludeText,
fullText:fullText,
aiSummary:aiSummary,
subpages:subpages,
subpageTarget:subpageTargetValue,
livecrawl:livecrawlVal,
livecrawlTimeout:livecrawlTimeoutVal,
links:linksVal
};
}
function handleSubmitResearchTask(){
const goal=pendingResearchGoal;
if(!goal){
return;
}
const options=buildOptionsFromForm();
hideResearchOptionsSheet();
startResearchTask(goal,options);
}
async function startResearchTask(goal,options){
const payload={
goal:goal,
search_type:options.searchType,
category:options.category,
user_location:options.userLocation,
start_published_date:options.startDate,
end_published_date:options.endDate,
start_crawl_date:options.startCrawlDate,
end_crawl_date:options.endCrawlDate,
include_domains:options.includeDomains&&options.includeDomains.length>0?options.includeDomains:null,
exclude_domains:options.excludeDomains&&options.excludeDomains.length>0?options.excludeDomains:null,
include_text:options.includeText,
exclude_text:options.excludeText,
full_text:options.fullText,
ai_summary:options.aiSummary,
subpages:options.subpages,
subpage_target:options.subpageTarget,
livecrawl:options.livecrawl,
livecrawl_timeout:options.livecrawlTimeout,
links:options.links
};
try{
const res=await fetch("/api/research/create",{
method:"POST",
headers:{"Content-Type":"application/json"},
body:JSON.stringify(payload)
});
if(!res.ok){
let errorData=null;
try{
errorData=await res.json();
}
catch(e){}
const message=errorData&&errorData.error?String(errorData.error):"Failed to create research task";
throw new Error(message);
}
const responseData=await res.json();
const taskId=responseData.task_id;
researchTasks[taskId]={
id:taskId,
goal:goal,
options:options,
status:"Indítás…",
progress:0,
sub_agents:[],
sources:[],
report:""
};
addResearchWidgetToHistory(taskId,goal,options);
pollResearchStatus(taskId);
}
catch(e){
addMessageToHistory("Kutatási feladat indítása sikertelen: "+String(e.message||e),"ai",null,true,true);
}
}
function pollResearchStatus(taskId){
const intervalId=setInterval(async()=>{
try{
const res=await fetch("/api/research/"+encodeURIComponent(taskId));
if(!res.ok){
clearInterval(intervalId);
throw new Error("Failed to fetch research status");
}
const data=await res.json();
if(!researchTasks[taskId]){
researchTasks[taskId]={};
}
researchTasks[taskId].status=data.status;
researchTasks[taskId].progress=data.progress;
researchTasks[taskId].sub_agents=data.sub_agents||[];
researchTasks[taskId].sources=data.sources||[];
researchTasks[taskId].report=data.report||"";
updateResearchWidget(taskId);
if(activeTaskId===taskId){
renderResearchViewContent(taskId);
}
const statusText=String(data.status||"");
if(statusText==="Befejezve"||statusText.startsWith("Hiba")){
clearInterval(intervalId);
}
}
catch(e){
clearInterval(intervalId);
console.error("Failed to fetch research status",e);
}
},2000);
}
function addResearchWidgetToHistory(taskId,goal,options){
if(!chatHistory){
return;
}
const widgetId="widget-"+taskId;
const messageElement=document.createElement("div");
messageElement.className="message widget";
messageElement.id=widgetId;
messageElement.setAttribute("data-task-id",taskId);
const hasOptions=!!(options.startDate||options.endDate||(options.includeDomains&&options.includeDomains.length>0)||(options.excludeDomains&&options.excludeDomains.length>0)||options.category);
const paramsSummary=hasOptions?"<div class=\"widget-params\">Egyéni szűrők alkalmazva</div>":"";
messageElement.innerHTML="<div class=\"widget-title\">AI Kutatási Feladat</div><div class=\"widget-goal\">"+goal+"</div>"+paramsSummary+"<div class=\"widget-status\">Státusz: Indítás…</div><div class=\"widget-progress\"><div class=\"widget-progress-inner\" style=\"width:0%\"></div></div>";
messageElement.addEventListener("click",()=>{
showResearchView(taskId);
});
chatHistory.appendChild(messageElement);
scrollToBottom();
}
function updateResearchWidget(taskId){
const task=researchTasks[taskId];
if(!task){
return;
}
const widget=document.getElementById("widget-"+taskId);
if(!widget){
return;
}
const statusEl=widget.querySelector(".widget-status");
const progressEl=widget.querySelector(".widget-progress-inner");
if(statusEl){
statusEl.textContent="Státusz: "+String(task.status);
}
if(progressEl){
progressEl.style.width=String(task.progress)+"%";
}
if(task.progress===100&&statusEl){
statusEl.textContent="✅ Státusz: Befejezve";
}
}
function showResearchView(taskId){
activeTaskId=taskId;
const task=researchTasks[taskId];
if(!task){
return;
}
const goalText=String(task.goal||"");
if(researchTitle){
if(goalText.length>25){
researchTitle.textContent=goalText.slice(0,25)+"…";
}
else{
researchTitle.textContent=goalText;
}
}
renderResearchViewContent(taskId);
if(chatView){
chatView.classList.add("research-active");
}
if(researchView){
researchView.classList.add("visible");
}
}
function createDonutChart(agent,globalProgress){
const statusText=String(agent.status||"");
let progressValue=0;
if(statusText==="Aktív"||statusText.includes("Collecting")||statusText.includes("Analyzing")||statusText.includes("Generating")){
progressValue=globalProgress;
}
else if(statusText==="Befejezve"||statusText.toLowerCase().includes("completed")||statusText.toLowerCase().includes("prepared")){
progressValue=100;
}
else{
progressValue=0;
}
const radius=24;
const circumference=2*Math.PI*radius;
const offset=circumference-(progressValue/100)*circumference;
const color=progressValue===100?"#34C759":"var(--accent-blue)";
const svg="<svg class=\"donut\" width=\"60\" height=\"60\" viewBox=\"0 0 60 60\"><circle class=\"donut-bg\" cx=\"30\" cy=\"30\" r=\""+radius+"\" fill=\"transparent\" stroke=\"rgba(255,255,255,0.1)\" stroke-width=\"6\"></circle><circle class=\"donut-progress\" cx=\"30\" cy=\"30\" r=\""+radius+"\" fill=\"transparent\" stroke=\""+color+"\" stroke-width=\"6\" stroke-dasharray=\""+circumference+"\" stroke-dashoffset=\""+offset+"\" stroke-linecap=\"round\"></circle><text x=\"50%\" y=\"50%\" dominant-baseline=\"middle\" text-anchor=\"middle\" class=\"donut-text\">"+progressValue.toString()+"%</text></svg>";
return svg;
}
function renderResearchViewContent(taskId){
const task=researchTasks[taskId];
if(!task||!researchContent){
return;
}
let agentsHtml="";
if(task.sub_agents&&task.sub_agents.length>0){
agentsHtml=task.sub_agents.map(agent=>{
const chart=createDonutChart(agent,task.progress);
const name=String(agent.name||"");
const status=String(agent.status||"");
return"<div class=\"agent-item\">"+chart+"<div class=\"agent-meta\"><div class=\"agent-name\">"+name+"</div><div class=\"agent-status\">"+status+"</div></div></div>";
}).join("");
}
else{
agentsHtml="<div class=\"agents-empty\">Ágensek inicializálása…</div>";
}
let sourcesHtml="";
if(task.sources&&task.sources.length>0){
sourcesHtml=task.sources.slice(0,10).map(source=>{
const title=source.title||"Untitled";
const url=source.url||"";
return"<div class=\"source-item\"><div class=\"source-title\">"+title+"</div><div class=\"source-url\">"+url+"</div></div>";
}).join("");
}
else{
sourcesHtml="<div class=\"sources-empty\">Források gyűjtése…</div>";
}
const reportText=task.report&&task.report.length>0?task.report:"A jelentés generálása folyamatban…";
researchContent.innerHTML="<section class=\"research-section\"><h3>Al-Ágensek Státusza</h3>"+agentsHtml+"</section><section class=\"research-section\"><h3>Források (Top 10)</h3>"+sourcesHtml+"</section><section class=\"research-section\"><h3>AI Jelentés</h3><div class=\"research-report\">"+reportText+"</div></section>";
}
function viewResearchTask(taskId){
if(researchTasks[taskId]){
showResearchView(taskId);
}
}
function handleFileUpload(event){
const input=event.target;
const file=input&&input.files&&input.files[0]?input.files[0]:null;
if(!file){
return;
}
addMessageToHistory("📎 Fájl feltöltése: "+file.name,"user",null,false,true);
addMessageToHistory(null,"ai","typing-indicator",false,false);
const formData=new FormData();
formData.append("file",file);
fetch("/api/upload",{
method:"POST",
body:formData
}).then(async res=>{
if(!res.ok){
let errorData=null;
try{
errorData=await res.json();
}
catch(e){}
const msg="HTTP "+res.status+": "+res.statusText;
throw new Error(errorData&&errorData.error?errorData.error:msg);
}
const result=await res.json();
const sizeKb=(result.size||0)/1024;
const sizeText=sizeKb.toFixed(2);
let responseMessage="✅ Fájl sikeresen feltöltve!\n\n📄 Fájlnév: "+String(result.original_filename||file.name)+"\n📊 Méret: "+sizeText+" KB\n🔖 Típus: "+String(result.type||"ismeretlen")+"\n\n🤖 AI Elemzés:\n"+String(result.analysis||"");
if(result.content_preview&&Array.isArray(result.content_preview)?result.content_preview.length>0:String(result.content_preview).length>0){
responseMessage=responseMessage+"\n\n📝 Tartalom előnézet:\n"+String(result.content_preview);
}
updateMessageInHistory("typing-indicator",responseMessage,"ai",false);
}).catch(err=>{
updateMessageInHistory("typing-indicator","Hiba történt a fájl feltöltése közben: "+String(err.message||err),"ai",true);
}).finally(()=>{
if(input){
input.value="";
}
});
}
